    /* ---- src/preview.js ---- */
/*
 * dsh-whale-maid — preview gallery (2.0.0).
 *
 * Twelve animation states plus every portrait that shipped in POSES, as a
 * clickable grid, so the whole art set can be inspected without waiting for
 * the scene that happens to use it.
 */

var DWM_PREVIEW_STATES = [
	['idle', '待机'], ['joy', '开心'], ['eat', '吃东西'], ['play', '玩耍'],
	['welcome', '欢迎'], ['drag', '被拖'], ['think', '思考'], ['work', '工作'],
	['sad', '沮丧'], ['sleep', '睡觉'], ['wake', '醒来'], ['walk', '走路'],
	['wink', '眨眼'],
];

var DWM_PREVIEW_POSE_LABELS = {
	waiting: '期待', curious: '好奇', teasing: '逗你', afk: '发呆', blush: '害羞',
	angry: '生气', star: '星星', night: '深夜', wink: '眨眼', bold: '自信',
	abstract: '漂浮', sweep: '扫地', workSlack: '摸鱼', workRam: '狂敲键盘',
	coolShades: '墨镜', balanceLow: '站不稳', workPat: '被摸头',
	success: '成功', celebrate: '庆祝',
};

function dwmPreviewPlayState(name) {
	dwmForceState(name, 3000);
}

function dwmPreviewPlayPose(name) {
	var image = dwmPoseImage(name);
	if (!image) {
		dwmSpeak('这张姿势图还没进包：' + name, 'error', 'important');
		return;
	}
	dwmPortraitShow({ context: name, pose: name, image: image, state: null }, 4000, true);
	dwmSpeak(DWM_PREVIEW_POSE_LABELS[name] || name, 'normal', 'important');
}

function dwmPreviewCell(label, sub, onPick) {
	return h(
		'button',
		{
			key: 'cell-' + label + '-' + sub,
			type: 'button',
			className: 'dwm-preview-cell',
			onClick: onPick,
			title: label + ' / ' + sub,
			style: {
				display: 'inline-flex',
				flexDirection: 'column',
				alignItems: 'center',
				gap: '2px',
				minWidth: '64px',
				padding: '6px 8px',
				cursor: 'pointer',
				borderRadius: '8px',
				border: '1px solid var(--dsw-alias-border-l2, #e2e4ea)',
				background: 'var(--dsw-alias-bg-layer-2, #fff)',
				color: 'var(--dsw-alias-label-primary, #1c1f26)',
				font: 'inherit',
			},
		},
		h('span', { style: { fontSize: '13px' } }, label),
		h('span', { style: { fontSize: '11px', opacity: 0.6 } }, sub),
	);
}

function PosePreviewPanel() {
	var poses = typeof dwmPoseList === 'function' ? dwmPoseList() : [];
	var stateCells = DWM_PREVIEW_STATES.map(function (pair) {
		return dwmPreviewCell(pair[1], pair[0], function () { dwmPreviewPlayState(pair[0]); });
	});
	var poseCells = poses.map(function (name) {
		return dwmPreviewCell(DWM_PREVIEW_POSE_LABELS[name] || name, name, function () { dwmPreviewPlayPose(name); });
	});
	return h(
		'div',
		{ className: 'dwm-settings-group' },
		h('h3', { style: { margin: '0 0 4px', fontSize: '14px' } }, '动作与姿势预览'),
		h('p', { style: { margin: '0 0 8px', fontSize: '12px', opacity: 0.65 } }, '点一下就在桌面上播一次，持续 3–4 秒。'),
		h('div', { style: { display: 'flex', flexWrap: 'wrap', gap: '6px', marginBottom: '10px' } }, stateCells),
		h('div', { style: { fontSize: '12px', opacity: 0.65, margin: '0 0 6px' } }, '姿势立绘（' + poses.length + ' 张）'),
		h('div', { style: { display: 'flex', flexWrap: 'wrap', gap: '6px' } }, poseCells),
	);
}

    /* ---- src/weather-ui.js ---- */
/*
 * dsh-whale-maid — city picker (2.2.0).
 *
 * Self-contained so it does not depend on the companion panel internals: a
 * status line, a search box and a candidate list. Picking a candidate writes
 * the city, refreshes the weather and confirms with a bubble.
 */

function dwmCityStatusText() {
	var record = typeof dwmWeatherRead === "function" ? dwmWeatherRead() : null;
	if (!record || !record.city) return "还没有天气数据，先选一个城市。";
	var parts = [record.city];
	if (typeof record.tempC === "number") parts.push(Math.round(record.tempC) + "°C");
	if (record.precision === "coordinates") parts.push("（仅坐标）");
	else if (record.precision === "city") parts.push("（市级）");
	return parts.join(" · ");
}

function WeatherCityPicker() {
	var queryState = useState("");
	var query = queryState[0];
	var setQuery = queryState[1];
	var listState = useState([]);
	var candidates = listState[0];
	var setCandidates = listState[1];
	var noteState = useState("");
	var note = noteState[0];
	var setNote = noteState[1];

	function search() {
		var text = typeof query === "string" ? query.trim() : "";
		if (text === "") { setCandidates([]); setNote("请输入城市名，例如「杭州」或「朝阳区」。"); return; }
		setNote("查询中…");
		if (typeof dwmWeatherCandidates !== "function") { setNote("当前版本不支持候选查询。"); return; }
		dwmWeatherCandidates(text).then(function (rows) {
			setCandidates(rows);
			setNote(rows.length === 0 ? "没找到匹配的城市，试试加省份，例如「浙江 杭州」。" : "点一个候选项即可生效。");
		});
	}

	function pick(candidate) {
		var next = normalizeOptions(Object.assign({}, readOptions(), { city: candidate.label }));
		writeJSON(KEY_OPTIONS, next);
		if (typeof window !== "undefined" && window.dispatchEvent) window.dispatchEvent(new CustomEvent(OPTIONS_EVENT));
		if (typeof dwmWeatherRefresh === "function") dwmWeatherRefresh();
		setCandidates([]);
		setNote("已切换到 " + candidate.label);
		dwmSpeak("已切换到 " + candidate.label, "important");
	}

	var rows = candidates.map(function (candidate) {
		return h("button", {
			key: "cand-" + candidate.label + candidate.lat,
			type: "button",
			onClick: function () { pick(candidate); },
			style: {
				display: "block", width: "100%", textAlign: "left", margin: "0 0 4px",
				padding: "6px 10px", cursor: "pointer", font: "inherit", borderRadius: "8px",
				border: "1px solid var(--dsw-alias-border-l2, #e2e4ea)",
				background: "var(--dsw-alias-bg-layer-2, #fff)",
				color: "var(--dsw-alias-label-primary, #1c1f26)",
			},
		}, candidate.label);
	});

	return h("div", { className: "dwm-settings-group" },
		h("p", { style: { margin: "0 0 6px", fontSize: "12px", opacity: 0.7 } }, dwmCityStatusText()),
		h("div", { style: { display: "flex", gap: "6px", marginBottom: "6px" } },
			h("input", {
				type: "text",
				value: query,
				onChange: function (event) { setQuery(event && event.target ? event.target.value : ""); },
				onKeyDown: function (event) { if (event && event.key === "Enter") search(); },
				placeholder: "城市不对？输入城市名回车，从候选里选",
				style: {
					flex: "1 1 auto", padding: "6px 10px", font: "inherit", borderRadius: "8px",
					border: "1px solid var(--dsw-alias-border-l2, #e2e4ea)",
					background: "var(--dsw-alias-bg-layer-1, #fff)",
					color: "var(--dsw-alias-label-primary, #1c1f26)",
				},
			}),
			h("button", { type: "button", onClick: search, style: { padding: "6px 12px", cursor: "pointer", font: "inherit", borderRadius: "8px", border: "1px solid var(--dsw-alias-border-l2, #e2e4ea)", background: "var(--dsw-alias-bg-layer-2, #fff)", color: "var(--dsw-alias-label-primary, #1c1f26)" } }, "查询"),
		),
		note === "" ? null : h("p", { style: { margin: "0 0 6px", fontSize: "12px", opacity: 0.7 } }, note),
		rows,
	);
}

    /* ---- src/signals.js ---- */
/*
 * dsh-whale-maid — work-status link (added in 1.1.0).
 *
 * The pet reacts to what the Harness is doing. There is no host-side event for
 * "a tool is running" (the client bus only carries session-level channels), so
 * this is a pure DOM observer. Every selector below was verified against the
 * DSH 0.2.1-rc.3 client bundles:
 *
 *   [data-chat-running]                       mounted only while a session runs
 *                                             (dsh-client-ui-chat, RunningStatus)
 *   [data-tool][data-state=running|preparing] a tool card is live
 *                                             (dsh-client-ui-tool, ToolRow)
 *   [data-tool][data-state=ok|error|stopped]  a finished card — it STAYS in the
 *                                             DOM, so it can never be a busy signal
 *   [data-variant=think][data-state=running]  a reasoning block is streaming
 *   [data-process-activity=thinking]          fallback when there is no reasoning
 *
 * Two consequences drive the design:
 *
 *   1. Finished cards persist, so "is there an error card?" is useless as an
 *      error signal. We compare counts against a baseline taken when the session
 *      started instead, which also survives history paging.
 *   2. `data-chat-running` belongs to the *mounted* session view: opening the
 *      settings page unmounts it while the session may still be running. The
 *      `workHold` grace period (default 6 s) papers over that and over the gap
 *      between two tool cards.
 *
 * 1.8.0 (A5) revisited both consequences:
 *
 *   - The 1.5 s interval was pure waste: a turn lasts minutes, and the mutation
 *     observer already catches every relevant DOM change. The interval is now
 *     `DWM_SIGNAL_POLL_MS` (3 s) and only acts as a floor, not as the detector.
 *   - A missing running marker is no longer read as "the turn ended" when the
 *     document is hidden or the settings view is mounted: both unmount the chat
 *     view without ending the turn. Those two cases HOLD instead of ending, and
 *     `visibilitychange` forces an immediate rescan the moment the tab comes
 *     back. `workHold` stays as the final safety net.
 *
 * Nothing here writes to the host DOM, so a future attribute change can break
 * the link but can never break the UI.
 */

var DWM_SIGNAL_SELECTORS = {
	running: ['[data-chat-running]'],
	tool: ['[data-tool][data-state="running"]', '[data-tool][data-state="preparing"]'],
	thinking: ['[data-variant="think"][data-state="running"]', '[data-streaming][data-variant="think"]'],
	activity: ['[data-process-activity="thinking"]'],
	error: ['[data-tool][data-state="error"]'],
	code: ['pre'],
	/**
	 * The settings view. Opening it replaces the session view, so
	 * `[data-chat-running]` disappears even though the turn is still running.
	 * Both selectors are the ones this repo already relies on for the settings
	 * surface (`settings.section` is registered in plugin.js, and
	 * `[data-shortcut-modal="settings"]` is the modal route into it).
	 */
	settings: ['[data-shortcut-modal="settings"]', '[data-slot="settings.header"]']
};

/** 1.8.0 (A5): the poll floor. The mutation observer does the real work. */
var DWM_SIGNAL_POLL_MS = 3000;
/** A turn running longer than this gets the "long" pose / line. */
var DWM_WORK_LONG_MS = 12 * 60000;

var DWM_SIGNAL_TIMERS = { interval: undefined, debounce: undefined, observer: null, visibility: null };

function dwmCountAny(selectorList) {
	var total = 0;
	for (var i = 0; i < selectorList.length; i++) {
		try {
			total += document.querySelectorAll(selectorList[i]).length;
		} catch (error) {
			/* an invalid selector must never throw out of the scan */
		}
	}
	return total;
}

function dwmQueryAny(selectorList) {
	return dwmCountAny(selectorList) > 0;
}

function dwmWorkPose(phase) {
	if (phase === 'thinking') return 'think';
	if (phase === 'tool') return 'work';
	if (phase === 'failure') return 'sad';
	if (phase === 'success') return 'joy';
	return 'idle';
}

/**
 * 1.8.0 (A5): the same phases, as keys of the pose map in `src/pose-map.js`.
 * 'long' is not a phase of its own — it is the tool phase once the turn has
 * been running past `DWM_WORK_LONG_MS`.
 */
function dwmWorkPoseContext(phase) {
	if (phase === 'thinking') return 'workThinking';
	if (phase === 'tool') {
		var since = DWM_RUNTIME.work.since;
		if (since && dwmNow() - since > DWM_WORK_LONG_MS) return 'workLong';
		return 'workTool';
	}
	if (phase === 'failure') return 'workFailure';
	if (phase === 'success') return 'workSuccess';
	return '';
}

/** True while the document is in a background tab. */
function dwmDocumentHidden() {
	return typeof document !== 'undefined' && document.visibilityState === 'hidden';
}

/** True while the settings view is mounted over the session. */
function dwmSettingsViewOpen() {
	return dwmQueryAny(DWM_SIGNAL_SELECTORS.settings);
}

function dwmWorkChipText(phase, language) {
	var zh = language === 'zh';
	if (phase === 'thinking') return zh ? '思考中 · 正在琢磨你的问题' : 'Thinking · working out your question';
	if (phase === 'tool') {
		var busyMs = DWM_RUNTIME.work.since ? dwmNow() - DWM_RUNTIME.work.since : 0;
		if (busyMs > DWM_WORK_LONG_MS) {
			return zh ? '还在忙 · 这个任务有点大，我在盯着' : 'Still busy · this task is a big one, I am watching it';
		}
		return zh ? '工作中 · 正在调用工具处理' : 'Working · running tools for you';
	}
	if (phase === 'failure') return zh ? '出错 · 需要你看一眼' : 'Error · needs your eyes';
	if (phase === 'success') return zh ? '完成 · 交给你了' : 'Done · handing it over';
	return '';
}

/**
 * Push the current phase onto the pet unless the user is dragging her.
 *
 * 1.8.0: the phase now goes through the pose map. Every work portrait is still
 * pending art, so `dwmPoseFor` returns the same animation state the 1.1.0 code
 * forced (`think` / `work` / `joy` / `sad`) and nothing changes on screen; the
 * moment a portrait ships, that portrait takes over instead.
 */
function dwmApplyWorkPoseRaw(phase) {
	dwmSetWorkGlow(phase !== 'idle');
	if (DWM_RUNTIME.state === 'drag') return;
	if (phase === 'idle') return;
	var context = dwmWorkPoseContext(phase);
	if (context !== '' && typeof dwmPoseFor === 'function') {
		var pose = dwmPoseFor(context);
		if (pose && (pose.image || pose.state)) {
			dwmShowPose(pose, 0, true);
			return;
		}
	}
	dwmForceState(dwmWorkPose(phase), 0, true);
}

function dwmResetWork(work) {
	dwmSetWorkGlow(false);
	dwmHidePose();
	work.active = false;
	work.phase = 'idle';
	work.held = false;
	work.longShown = false;
	work.hadError = false;
	work.hadTool = false;
	work.hadCode = false;
	work.base = null;
}

function dwmScanSignals() {
	var companion = dwmReadCompanion();
	var work = DWM_RUNTIME.work;
	var now = dwmNow();

	if (!companion.workLink) {
		dwmResetWork(work);
		return;
	}

	var hasTool = dwmQueryAny(DWM_SIGNAL_SELECTORS.tool);
	var hasThinking = dwmQueryAny(DWM_SIGNAL_SELECTORS.thinking) || dwmQueryAny(DWM_SIGNAL_SELECTORS.activity);
	var hasRunning = dwmQueryAny(DWM_SIGNAL_SELECTORS.running);

	var phase = 'idle';
	if (hasTool) phase = 'tool';
	else if (hasThinking && (hasRunning || work.active)) phase = 'thinking';
	else if (hasRunning) phase = 'thinking';

	if (phase !== 'idle') {
		if (!work.active) {
			/* a new work session begins — take the baselines first */
			work.active = true;
			work.sessions += 1;
			work.since = now;
			work.hadError = false;
			work.hadTool = false;
			work.hadCode = false;
			work.base = {
				error: dwmCountAny(DWM_SIGNAL_SELECTORS.error),
				code: dwmCountAny(DWM_SIGNAL_SELECTORS.code)
			};
			dwmGrowthApply('tool-seen');
			dwmApplyWorkPose(phase);
			if (companion.chip) dwmChip(dwmWorkChipText(phase, dwmUiLanguage()), 'work', 2400, 'state');
			if (DWM_RUNTIME.api && DWM_RUNTIME.api.resetSleep) DWM_RUNTIME.api.resetSleep();
			if (DWM_RUNTIME.api && DWM_RUNTIME.api.stopWalk) DWM_RUNTIME.api.stopWalk();
		}
		if (phase === 'tool') work.hadTool = true;

		/* errors are counted against the baseline, never against bare presence */
		if (work.base && dwmCountAny(DWM_SIGNAL_SELECTORS.error) > work.base.error) work.hadError = true;

		if (phase !== work.phase) {
			work.phase = phase;
			work.changedAt = now;
			dwmApplyWorkPose(phase);
			if (companion.chip && phase !== 'thinking') {
				dwmChip(dwmWorkChipText(phase, dwmUiLanguage()), 'work', 2400, 'state');
			}
		} else if (phase === 'tool' && !work.longShown && now - work.since > DWM_WORK_LONG_MS) {
			/*
			 * A5: the turn crossed the "long" threshold without changing phase, so
			 * nothing above would repaint. Do it once, and only once, per session.
			 */
			work.longShown = true;
			dwmApplyWorkPose('tool');
			if (companion.chip) dwmChip(dwmWorkChipText('tool', dwmUiLanguage()), 'work', 2400, 'state');
		}
		work.goneAt = now;
		work.held = false;

		/* keep her awake and still while a turn is running */
		if (DWM_RUNTIME.api && DWM_RUNTIME.api.resetSleep) DWM_RUNTIME.api.resetSleep();
		if (DWM_RUNTIME.api && DWM_RUNTIME.api.stopWalk) DWM_RUNTIME.api.stopWalk();

		if (!work.hadCode && work.base && dwmCountAny(DWM_SIGNAL_SELECTORS.code) > work.base.code) {
			work.hadCode = true;
			dwmGrowthApply('code-seen');
		}
		return;
	}

	/* no busy marker right now */
	if (!work.active) {
		work.phase = 'idle';
		return;
	}
	/*
	 * A5: an unmounted session view is not a finished turn. Both the settings
	 * page and a background tab unmount `[data-chat-running]` while the turn
	 * keeps running, so hold the phase instead of ending it. `workHold` below
	 * still ends the turn if neither condition ever clears.
	 */
	if (dwmSettingsViewOpen() || dwmDocumentHidden()) {
		work.held = true;
		return;
	}
	if (now - work.goneAt < companion.workHold) {
		work.held = true;
		return;
	}

	/* the session is over */
	var failed = work.hadError === true;
	dwmResetWork(work);
	if (failed) {
		dwmGrowthApply('failure');
		dwmPlayWorkOutcome('workFailure', 'sad', 2000);
		if (companion.chip) dwmChip(dwmWorkChipText('failure', dwmUiLanguage()), 'error', 2600, 'state');
		dwmFx('sparkle', 2);
		if (companion.workSpeech !== 'off') dwmSpeak(dwmPickLine('workFailure', dwmUiLanguage()), undefined, 'state');
	} else {
		dwmGrowthApply('success');
		dwmPlayWorkOutcome('workSuccess', 'joy', 1500);
		if (companion.chip) dwmChip(dwmWorkChipText('success', dwmUiLanguage()), 'ok', 2200, 'state');
		dwmFx('star', 3);
		if (companion.workSpeech !== 'off') dwmSpeak(dwmPickLine('workSuccess', dwmUiLanguage()), undefined, 'state');
	}
}

/**
 * The closing pose of a turn. A portrait wins when one is shipped; otherwise the
 * 1.1.0 sequence runs unchanged, so the outcome looks exactly as it always did.
 */
function dwmPlayWorkOutcome(context, state, ms) {
	if (typeof dwmPoseFor === 'function') {
		var pose = dwmPoseFor(context);
		if (pose && (pose.image || pose.state)) {
			dwmShowPose(pose, ms);
			return;
		}
	}
	dwmPlaySequence([[state, ms]]);
}

/**
 * Play a short pose sequence. Before the pet mounts there is no sequence
 * runner yet, so fall back to announcing the first state on the same event
 * channel the pet listens to.
 */
function dwmPlaySequence(steps) {
	if (!steps || !steps.length) return;
	var api = DWM_RUNTIME.api;
	if (api && typeof api.runSequence === 'function') {
		api.runSequence(steps);
		return;
	}
	dwmForceState(steps[0][0], steps[0][1]);
}

/** Which language the visible text should use (mirrors resolveLanguage). */
function dwmUiLanguage() {
	try {
		return resolveLanguage(readOptions().language);
	} catch (error) {
		return 'zh';
	}
}

function dwmScheduleScan() {
	if (DWM_SIGNAL_TIMERS.debounce !== undefined) clearTimeout(DWM_SIGNAL_TIMERS.debounce);
	DWM_SIGNAL_TIMERS.debounce = setTimeout(function () {
		DWM_SIGNAL_TIMERS.debounce = undefined;
		dwmScanSignals();
	}, 200);
}

function dwmStartSignals() {
	dwmStopSignals();
	dwmScheduleScan();
	DWM_SIGNAL_TIMERS.interval = setInterval(dwmScanSignals, DWM_SIGNAL_POLL_MS);
	if (typeof MutationObserver === 'function' && document.body) {
		DWM_SIGNAL_TIMERS.observer = new MutationObserver(dwmScheduleScan);
		DWM_SIGNAL_TIMERS.observer.observe(document.body, {
			childList: true,
			subtree: true,
			attributes: true,
			attributeFilter: ['data-chat-running', 'data-tool', 'data-state', 'data-variant', 'data-streaming', 'data-process-activity']
		});
	}
	/*
	 * A5: a hidden tab stops mutating, so the interval is the only thing that
	 * could notice the turn ending — and it is now 3 s. Coming back to the tab is
	 * the one moment where being late is visible, so rescan right away instead of
	 * waiting for the next tick.
	 */
	if (typeof document !== 'undefined' && typeof document.addEventListener === 'function') {
		DWM_SIGNAL_TIMERS.visibility = function () {
			if (dwmDocumentHidden()) return;
			if (DWM_SIGNAL_TIMERS.debounce !== undefined) clearTimeout(DWM_SIGNAL_TIMERS.debounce);
			DWM_SIGNAL_TIMERS.debounce = undefined;
			dwmScanSignals();
		};
		document.addEventListener('visibilitychange', DWM_SIGNAL_TIMERS.visibility);
	}
	return dwmStopSignals;
}

function dwmStopSignals() {
	if (DWM_SIGNAL_TIMERS.interval !== undefined) clearInterval(DWM_SIGNAL_TIMERS.interval);
	if (DWM_SIGNAL_TIMERS.debounce !== undefined) clearTimeout(DWM_SIGNAL_TIMERS.debounce);
	DWM_SIGNAL_TIMERS.interval = undefined;
	DWM_SIGNAL_TIMERS.debounce = undefined;
	if (DWM_SIGNAL_TIMERS.visibility) {
		if (typeof document !== 'undefined' && typeof document.removeEventListener === 'function') {
			try {
				document.removeEventListener('visibilitychange', DWM_SIGNAL_TIMERS.visibility);
			} catch (error) {
				/* ignore */
			}
		}
		DWM_SIGNAL_TIMERS.visibility = null;
	}
	if (DWM_SIGNAL_TIMERS.observer) {
		try {
			DWM_SIGNAL_TIMERS.observer.disconnect();
		} catch (error) {
			/* ignore */
		}
		DWM_SIGNAL_TIMERS.observer = null;
	}
}

/*
 * Pose changes are debounced: a turn alternates between "thinking" and
 * "running a tool" every few hundred milliseconds, which used to flip the
 * sprite between think.png and work.png and look like two pets fighting.
 * A new pose is only painted once it has been the truth for a moment, and
 * a running tool outranks a thinking blip so the work pose stays put.
 */
var DWM_WORK_POSE_STABLE_MS = 1500;
var DWM_WORK_POSE_STICKY_MS = 6000;
var DWM_WORK_POSE_LAST = { state: null, at: 0, toolAt: 0 };

function dwmApplyWorkPoseStable(state) {
	var now = dwmNow();
	if (state === 'work') DWM_WORK_POSE_LAST.toolAt = now;
	// A thinking blip right after a tool must not repaint: the turn alternates
	// between the two every few hundred ms and it reads as two pets fighting.
	if (state === 'think' && now - DWM_WORK_POSE_LAST.toolAt < DWM_WORK_POSE_STICKY_MS) return;
	if (state === DWM_WORK_POSE_LAST.state) return;
	DWM_WORK_POSE_LAST.state = state;
	DWM_WORK_POSE_LAST.at = now;
	dwmApplyWorkPoseRaw(state);
}


/* Callers keep using the old name; it now goes through the debounce. */
function dwmApplyWorkPose(state) {
	return dwmApplyWorkPoseStable(state);
}

    /* ---- src/care.js ---- */
/*
 * dsh-whale-maid — proactive care and small talk (added in 1.1.0).
 *
 * The store pet only ever spoke when clicked. This module gives her a sense of
 * time and of your work: she notices a long unbroken session, a stuck step, a
 * late night, an empty stomach, or that you were away for a while, and she keeps
 * a slow stream of small talk going while the conversation is idle.
 *
 * Everything is throttled and can be switched off per feature from the settings
 * panel. All timings are generous on purpose: a desktop pet that talks every
 * minute is a bug, not a feature.
 *
 * 1.8.0: two additions that both serve "care should not get lost in the noise".
 *
 *   - Care and milestone lines speak with priority 'important' (see
 *     `dwmSpeak`), so a routine work-status line can no longer talk over the
 *     one line that actually asks the user to stop working.
 *   - Every care moment now asks `src/pose-map.js` for its pose. When a
 *     portrait is shipped it is shown; when none is, the previous behaviour is
 *     kept exactly (`careComeBack` still plays `welcome`).
 */

var DWM_CARE = {
	heartbeat: undefined,
	idleChat: undefined,
	workSpeech: undefined,
	lastNightAt: 0,
	lastLongSitAt: 0,
	lastStuckAt: 0,
	lastHungryAt: 0,
	lastText: '',
	lastTextAt: 0,
	lastReactAt: 0,
	topic: 'general',
	signinDone: false,
	/** pending "put the work pose back" timer after a care pose */
	poseRestore: undefined
};

var DWM_CARE_RULES = {
	heartbeatMs: 30000,
	awayMs: 3 * 60000,
	longSitMs: 25 * 60000,
	longSitGapMs: 30 * 60000,
	stuckMs: 8 * 60000,
	stuckGapMs: 15 * 60000,
	hungryGapMs: 2 * 3600000,
	careGapMs: 15 * 60000,
	idleChatMinMs: 5 * 60000,
	idleChatJitterMs: 3 * 60000,
	workChattyMinMs: 15000,
	workChattyJitterMs: 25000,
	workQuietMinMs: 90000,
	workQuietJitterMs: 150000,
	speakGapMs: 12000,
	textReactGapMs: 20000
};

function dwmCareCanSpeak() {
	if (!DWM_RUNTIME.ready) return false;
	if (typeof document !== 'undefined' && document.visibilityState === 'hidden') return false;
	return dwmNow() - DWM_RUNTIME.lastSayAt > DWM_CARE_RULES.speakGapMs;
}

/**
 * Show the pose for a care moment.
 *
 * When the pose map names an animation state, that is an explicit instruction
 * and `dwmShowPose` handles it. When it names only a portrait, the portrait is
 * painted and a failed paint stays invisible on purpose: most care moments never
 * changed her animation before 1.8.0, and forcing a fallback state here would
 * clobber whatever she is legitimately doing — `careLongSit` fires *during* a
 * running turn, where the work pose must survive.
 */
function dwmCarePose(context, ms) {
	if (typeof dwmPoseFor !== 'function') return false;
	var pose = null;
	try {
		pose = dwmPoseFor(context);
	} catch (error) {
		return false;
	}
	if (!pose) return false;
	if (pose.state) {
		var shown = dwmShowPose(pose, ms);
		/*
		 * A care pose is a moment, but the work pose lasts a turn: without this
		 * the pet would finish her worried 3 s and then sit in `idle` for the rest
		 * of a long session, because the work pose is only repainted on a phase
		 * change. Put the turn's pose back when the care moment is over.
		 */
		if (shown && DWM_RUNTIME.work.active) {
			if (DWM_CARE.poseRestore !== undefined) clearTimeout(DWM_CARE.poseRestore);
			DWM_CARE.poseRestore = setTimeout(function () {
				DWM_CARE.poseRestore = undefined;
				if (!DWM_RUNTIME.work.active) return;
				if (typeof dwmApplyWorkPose === 'function') dwmApplyWorkPose(DWM_RUNTIME.work.phase);
			}, (Number(ms) > 0 ? Number(ms) : 2000) + 100);
		}
		return shown;
	}
	if (!pose.image) return false;
	return dwmPortraitShow(pose, ms);
}

function dwmCareMoodLine(language) {
	var growth = dwmGrowthRead();
	var tier = dwmMoodTier(growth.mood);
	if (tier === 2) return '';
	return dwmPickLine(dwmMoodBank(growth.mood), language);
}

/** Read the newest chat node's text, if the client exposes one. */
function dwmReadChatText() {
	var selectors = ['[data-slot="conversation.chat.node"]', '[data-role="user"]', '[data-message-role="user"]'];
	for (var i = 0; i < selectors.length; i++) {
		var nodes = null;
		try {
			nodes = document.querySelectorAll(selectors[i]);
		} catch (error) {
			nodes = null;
		}
		if (!nodes || nodes.length === 0) continue;
		var last = nodes[nodes.length - 1];
		var text = last && typeof last.textContent === 'string' ? last.textContent : '';
		text = text.replace(/\s+/g, ' ').trim();
		if (text !== '') return text.slice(-400);
	}
	return '';
}

/** Keyword reactions + topic tracking, driven by the newest chat text. */
function dwmReactToText() {
	var companion = dwmReadCompanion();
	var text = dwmReadChatText();
	if (text === '' || text === DWM_CARE.lastText) return;
	DWM_CARE.lastText = text;
	DWM_CARE.lastTextAt = dwmNow();
	DWM_CARE.topic = dwmClassifyTopic(text);
	var keyword = dwmMatchKeyword(text);
	if (!keyword) return;
	if (dwmNow() - DWM_CARE.lastReactAt < DWM_CARE_RULES.textReactGapMs) return;
	DWM_CARE.lastReactAt = dwmNow();
	dwmGrowthApply('keyword');
	if (companion.zones !== false) {
		dwmForceState(keyword.pose, 1800);
		dwmFx(keyword.fx || 'note', 2);
	}
	if (companion.chip) dwmChip(dwmKeywordChip(keyword, dwmUiLanguage()), 'mood', 2600);
}

function dwmKeywordChip(keyword, language) {
	var zh = language === 'zh';
	var table = {
		thanks: zh ? '嘿嘿，不客气～' : 'Hehe, welcome~',
		cute: zh ? '诶…说我可爱？' : 'Eh… cute?',
		slack: zh ? '摸鱼时间到！' : 'Slack time!',
		cheer: zh ? '一起冲！' : 'Let us go!',
		tired: zh ? '那就歇一会儿…' : 'Then rest a bit…',
		broken: zh ? '翻车了？我陪你。' : 'It broke? I am here.',
		yay: zh ? '好耶！' : 'Yay!',
		why: zh ? '唔…为什么呀？' : 'Hmm, why?',
		morning: zh ? '早上好！' : 'Good morning!',
		night: zh ? '晚安，做个好梦。' : 'Good night, sweet dreams.',
		laugh: zh ? '你笑了！' : 'You laughed!',
		pat: zh ? '要摸摸头吗？' : 'Head pats?',
		overtime: zh ? '又在加班吗…' : 'Overtime again…'
	};
	return table[keyword.id] || (zh ? '嗯嗯。' : 'Mm-hm.');
}

function dwmCareCheck() {
	var companion = dwmReadCompanion();
	var now = dwmNow();
	var work = DWM_RUNTIME.work;
	var language = dwmUiLanguage();

	/* 1. check in once per local day */
	if (!DWM_CARE.signinDone) {
		DWM_CARE.signinDone = true;
		var result = dwmGrowthSignin(now);
		if (result) {
			var streak = result.growth.signinStreak;
			if (companion.chip) {
				dwmChip(
					language === 'zh' ? '签到成功 · 连续 ' + streak + ' 天' : 'Checked in · ' + streak + ' day streak',
					'ok',
					3000,
					'important',
				);
			}
		}
	}

	/* 2. keyword / topic tracking is cheap and independent of the cooldowns */
	if (companion.zones !== false) dwmReactToText();

	if (!companion.care) return;
	if (now - DWM_RUNTIME.lastCareAt < DWM_CARE_RULES.careGapMs) return;

	/* 3. a long unbroken work session */
	if (work.active && now - work.since > DWM_CARE_RULES.longSitMs && now - DWM_CARE.lastLongSitAt > DWM_CARE_RULES.longSitGapMs) {
		if (dwmCareCanSpeak()) {
			DWM_CARE.lastLongSitAt = now;
			DWM_RUNTIME.lastCareAt = now;
			dwmSpeak(dwmPickLine('careLongSit', language), undefined, 'important');
			dwmCarePose('careLongSit', 3000);
			dwmFx('note', 1);
			return;
		}
	}

	/* 4. the same step has been running for a long time */
	if (work.active && work.changedAt && now - work.changedAt > DWM_CARE_RULES.stuckMs && now - DWM_CARE.lastStuckAt > DWM_CARE_RULES.stuckGapMs) {
		if (dwmCareCanSpeak()) {
			DWM_CARE.lastStuckAt = now;
			DWM_RUNTIME.lastCareAt = now;
			dwmSpeak(dwmPickLine('careStuck', language), undefined, 'important');
			dwmCarePose('careStuck', 3000);
			return;
		}
	}

	/* 5. late night, once per night */
	if (companion.lateNight && dwmIsLateNight(now) && now - DWM_CARE.lastNightAt > 6 * 3600000) {
		if (dwmCareCanSpeak()) {
			DWM_CARE.lastNightAt = now;
			DWM_RUNTIME.lastCareAt = now;
			dwmSpeak(dwmPickLine('careLateNight', language), undefined, 'important');
			dwmCarePose('careLateNight', 3000);
			return;
		}
	}

	/* 6. hungry */
	var growth = dwmGrowthRead();
	if (growth.satiety < 22 && now - DWM_CARE.lastHungryAt > DWM_CARE_RULES.hungryGapMs) {
		if (dwmCareCanSpeak()) {
			DWM_CARE.lastHungryAt = now;
			DWM_RUNTIME.lastCareAt = now;
			dwmSpeak(dwmPickLine('careSatiety', language), undefined, 'important');
			dwmCarePose('careSatiety', 3000);
			return;
		}
	}
}

function dwmCareHeartbeat() {
	var now = dwmNow();
	var previous = DWM_RUNTIME.lastSeenAt || now;
	var awayMs = now - previous;

	dwmGrowthTick(now);
	dwmGrowthHeartbeat(now);

	/* came back after a real absence */
	if (awayMs > DWM_CARE_RULES.awayMs) {
		dwmGrowthApply('click', { awayMs: awayMs });
		if (dwmReadCompanion().care && dwmCareCanSpeak()) {
			dwmSpeak(dwmPickLine('careComeBack', dwmUiLanguage()), undefined, 'important');
			dwmFx('heart', 2);
			/* a greeting portrait when one is shipped, otherwise the usual 'welcome' */
			var greet = typeof dwmPoseFor === 'function' ? dwmPoseFor('careComeBack') : null;
			if (greet) dwmShowPose(greet, 1600);
			else dwmForceState('welcome', 1600);
		}
	}

	dwmCareCheck();
	dwmScheduleIdleChat();
	dwmScheduleWorkSpeech();
}

function dwmScheduleIdleChat() {
	if (DWM_CARE.idleChat !== undefined) clearTimeout(DWM_CARE.idleChat);
	var companion = dwmReadCompanion();
	if (!companion.idleChat) return;
	var delay = DWM_CARE_RULES.idleChatMinMs + Math.random() * DWM_CARE_RULES.idleChatJitterMs;
	DWM_CARE.idleChat = setTimeout(function () {
		DWM_CARE.idleChat = undefined;
		dwmIdleChatTick();
		dwmScheduleIdleChat();
	}, delay);
}

function dwmIdleChatTick() {
	var companion = dwmReadCompanion();
	if (!companion.idleChat) return;
	if (!DWM_RUNTIME.ready) return;
	if (DWM_RUNTIME.work.active) return;
	if (typeof document !== 'undefined' && document.visibilityState === 'hidden') return;
	if (DWM_RUNTIME.state === 'sleep' || DWM_RUNTIME.state === 'drag') return;
	if (!dwmCareCanSpeak()) return;
	var language = dwmUiLanguage();
	var growth = dwmGrowthRead();
	var mood = dwmCareMoodLine(language);
	var line = mood !== '' ? mood : dwmPickLine('chat' + DWM_CARE.topic.charAt(0).toUpperCase() + DWM_CARE.topic.slice(1), language);
	if (line === '') line = dwmPickLine('chatGeneral', language);
	dwmSpeak(line);
	/* the mood line gets its own pose, so a low or high mood is visible, not just read */
	if (mood !== '') dwmCarePose(dwmMoodTier(growth.mood) <= 1 ? 'moodLow' : 'moodHigh', 3000);
	dwmGrowthApply('chat');
	DWM_RUNTIME.lastIdleChatAt = dwmNow();
}

function dwmScheduleWorkSpeech() {
	if (DWM_CARE.workSpeech !== undefined) clearTimeout(DWM_CARE.workSpeech);
	var companion = dwmReadCompanion();
	if (companion.workSpeech === 'off') return;
	var chatty = companion.workSpeech === 'chatty';
	var delay = chatty
		? DWM_CARE_RULES.workChattyMinMs + Math.random() * DWM_CARE_RULES.workChattyJitterMs
		: DWM_CARE_RULES.workQuietMinMs + Math.random() * DWM_CARE_RULES.workQuietJitterMs;
	DWM_CARE.workSpeech = setTimeout(function () {
		DWM_CARE.workSpeech = undefined;
		dwmWorkSpeechTick();
		dwmScheduleWorkSpeech();
	}, delay);
}

function dwmWorkSpeechTick() {
	var companion = dwmReadCompanion();
	if (companion.workSpeech === 'off') return;
	if (!DWM_RUNTIME.work.active) return;
	/* Work speech keeps its own 8s gap instead of the global care gate. */
	if (dwmNow() - (DWM_RUNTIME.lastWorkSpeechAt || 0) < 8000) return;
	var language = dwmUiLanguage();
	var phase = DWM_RUNTIME.work.phase;
	var busyMs = DWM_RUNTIME.work.since ? dwmNow() - DWM_RUNTIME.work.since : 0;
	var banks;
	if (busyMs > 12 * 60000) banks = ['workLong', 'careLongSit', 'workTool'];
	else if (phase === 'tool') banks = ['workTool', 'workThinking', 'chatGeneral'];
	else if (phase === 'thinking') banks = ['workThinking', 'workTool', 'chatGeneral'];
	else if (phase === 'failure') banks = ['workFailure', 'careStuck', 'chatDebug'];
	else if (phase === 'success') banks = ['workSuccess', 'chatGeneral'];
	else banks = ['workThinking', 'chatGeneral'];
	var line = dwmPickLineFrom(banks, language);
	/* work narration is 'state': it may replace itself, never a care line */
	if (line) dwmSpeak(line, undefined, 'state');
	DWM_RUNTIME.lastWorkSpeechAt = dwmNow();
}

function dwmCareGreetFirstMeet() {
	if (!DWM_RUNTIME.ready) return;
	var growth = dwmGrowthRead();
	if (growth.counts.click > 0 || growth.firstSeenAt === 0) return;
	if (!dwmCareCanSpeak()) return;
	dwmSpeak(dwmPickLine('hello', dwmUiLanguage()), undefined, 'important');
}

function dwmStartCare() {
	dwmStopCare();
	dwmCareHeartbeat();
	DWM_CARE.heartbeat = setInterval(dwmCareHeartbeat, DWM_CARE_RULES.heartbeatMs);
	dwmScheduleIdleChat();
	dwmScheduleWorkSpeech();
	return dwmStopCare;
}

function dwmStopCare() {
	if (DWM_CARE.heartbeat !== undefined) clearInterval(DWM_CARE.heartbeat);
	if (DWM_CARE.idleChat !== undefined) clearTimeout(DWM_CARE.idleChat);
	if (DWM_CARE.workSpeech !== undefined) clearTimeout(DWM_CARE.workSpeech);
	if (DWM_CARE.poseRestore !== undefined) clearTimeout(DWM_CARE.poseRestore);
	DWM_CARE.heartbeat = undefined;
	DWM_CARE.idleChat = undefined;
	DWM_CARE.workSpeech = undefined;
	DWM_CARE.poseRestore = undefined;
}

